/* Example for a responsive H1 */
h1 {
  font-size: clamp(2rem, 5vw + 1rem, 4rem);
  /* Explanation:
     - Minimum size: 2rem (e.g., on small screens)
     - Preferred size: 5vw + 1rem (scales with viewport width)
     - Maximum size: 4rem (e.g., on very large screens)
  */
  line-height: 1.2;
}

/* Example for responsive body text */
p {
  font-size: clamp(1rem, 0.8vw + 0.5rem, 1.25rem);
  line-height: 1.6;
}
